import{_ as a,C as r,o as c,c as l,j as o,a as e,E as i,a2 as s}from"./chunks/framework.DCaeQ2Kp.js";const g=JSON.parse('{"title":"momo-ws 协议 v1","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocol.md","filePath":"guide/protocol.md"}'),n={name:"guide/protocol.md"};function h(m,t,p,u,b,S){const d=r("DiagramFrame");return c(),l("div",null,[t[0]||(t[0]=o("h1",{id:"momo-ws-协议-v1",tabindex:"-1"},[e("momo-ws 协议 v1 "),o("a",{class:"header-anchor",href:"#momo-ws-协议-v1","aria-label":'Permalink to "momo-ws 协议 v1"'},"​")],-1)),t[1]||(t[1]=o("p",null,[e("进程间通信协议："),o("strong",null,"JSON 文本帧（控制面）+ 二进制音频帧（数据面），单连接复用"),e("。LLM 推理不在本协议内——编排器对大脑走 OpenAI-compatible HTTP SSE。")],-1)),i(d,{src:"turn-voice.html",height:640}),t[2]||(t[2]=s('<h2 id="连接拓扑" tabindex="-1">连接拓扑 <a class="header-anchor" href="#连接拓扑" aria-label="Permalink to &quot;连接拓扑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>链路</th><th>方向</th><th>用途</th></tr></thead><tbody><tr><td>UI 链路</td><td>前端 → 编排器 <code>/ws/ui</code></td><td>用户输入、字幕/表情、播放、状态广播</td></tr><tr><td>action 链路</td><td>action 方 → 编排器 <code>/ws/action</code></td><td>注册/执行 action（P4）</td></tr><tr><td>模型链路</td><td>编排器 → ASR/TTS <code>/ws</code></td><td>音频上行、合成下发、取消</td></tr></tbody></table><h2 id="握手" tabindex="-1">握手 <a class="header-anchor" href="#握手" aria-label="Permalink to &quot;握手&quot;">​</a></h2><p>建连后第一条消息必须是 <code>hello</code>（含 <code>protocol:&quot;momo-ws&quot;</code>、<code>version:&quot;v1&quot;</code>、<code>client</code> 角色、音频参数协商）；服务端回 <code>hello.ok</code>（<code>session_id</code>、<code>role</code>、<code>capabilities</code>）或 <code>error{VERSION_MISMATCH}</code> + close <code>4001</code>。</p><h2 id="消息目录" tabindex="-1">消息目录 <a class="header-anchor" href="#消息目录" aria-label="Permalink to &quot;消息目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>type</th><th>方向</th><th>何时发</th></tr></thead><tbody><tr><td><code>hello</code> / <code>hello.ok</code></td><td>双向</td><td>建连握手</td></tr><tr><td><code>input.text</code></td><td>UI→orch</td><td>用户提交文字</td></tr><tr><td><code>input.audio.segment</code></td><td>ASR→orch → UI 镜像</td><td>VAD 段转写完成</td></tr><tr><td><code>input.vad</code></td><td>ASR→orch → UI 镜像</td><td>speech_start/end 边界；Speaking 中即打断触发源</td></tr><tr><td><code>output.sentence</code></td><td>orch→UI + TTS</td><td>LLM 每成形一句（含 emotion）</td></tr><tr><td><code>audio.chunk</code></td><td>二进制双向</td><td>音频流</td></tr><tr><td><code>control.barge_in</code></td><td>UI↔orch→TTS/ASR</td><td>打断请求/通知/回报</td></tr><tr><td><code>control.cancel</code></td><td>orch→TTS/ASR/action</td><td>取消指定对象</td></tr><tr><td><code>state.turn</code></td><td>orch→UI</td><td>状态迁移广播</td></tr><tr><td><code>action.*</code></td><td>action 方↔orch</td><td>注册/调用/结果（P4）</td></tr><tr><td><code>error</code></td><td>双向</td><td>协议/运行错误</td></tr></tbody></table><h2 id="二进制音频帧" tabindex="-1">二进制音频帧 <a class="header-anchor" href="#二进制音频帧" aria-label="Permalink to &quot;二进制音频帧&quot;">​</a></h2><p>固定 12B 头 + 载荷：<code>ver(1B) | stream(1B: 0x01上行/0x02下行) | flags(2B, bit0=EOS) | seq(4B) | tag(4B: 下行=句seq / 上行=VAD段号) | payload</code>。 默认 <code>pcm_s16le</code> 单声道 50ms/帧；上行 16kHz、下行 24kHz（hello 协商）。</p><h2 id="emotion-tag" tabindex="-1">emotion tag <a class="header-anchor" href="#emotion-tag" aria-label="Permalink to &quot;emotion tag&quot;">​</a></h2><p>LLM 内联 <code>[happy]</code> 标注 → 编排器剥离写入 <code>output.sentence.emotion</code>。v1 固定 8 值：<code>neutral happy sad angry surprised thinking shy sleepy</code>。tag→Live2D 表情/TTS instruct 的映射是各端实现细节，不进协议。</p><h2 id="背压与断线" tabindex="-1">背压与断线 <a class="header-anchor" href="#背压与断线" aria-label="Permalink to &quot;背压与断线&quot;">​</a></h2><ul><li>下行音频<strong>永不静默丢帧</strong>：orch 缓冲 96 帧 ≈4.8s；溢出即 <code>BACKPRESSURE_OVERFLOW</code> + 取消回合。</li><li>上行丢旧帧（实时性优先），缓冲 2s；ASR 对 &gt;30s 段强制 final。</li><li>JSON 控制帧永不丢弃，消费不动即关连（close <code>4400</code>）。</li><li>UI 断连→取消活动回合保留历史；重连走 hello 重同步，不重放音频。</li><li>重连退避：指数 0.5s→8s，±20% 抖动。</li></ul><div class="info custom-block"><p class="custom-block-title">权威来源</p><p><a href="https://github.com/Momoyeyu/momo-docs/blob/master/01-architecture/protocol.md" target="_blank" rel="noreferrer">momo-docs/01-architecture/protocol.md</a> — 全部 JSON schema、close code、版本协商细则。</p></div>',13))])}const f=a(n,[["render",h]]);export{g as __pageData,f as default};
